package middleware

import (
	"crypto/subtle"
	"net/http"
	"strings"
	"sync"

	"github.com/DragonEmperor9480/AethrOps/constants"
	"github.com/DragonEmperor9480/AethrOps/utils"
)

// The API is reachable by anything on the device (browsers, other apps), so every
// request must carry the per-launch token generated by the Flutter app.
var (
	authToken   string
	authTokenMu sync.RWMutex
)

// Hosts accepted in the Host header. Anything else is rejected to block DNS rebinding.
var allowedHosts = map[string]bool{
	constants.BackendAddress:             true,
	"localhost:" + constants.BackendPort: true,
}

// SetAuthToken sets the token that every request must present.
// It can be called again (Android re-launch in the same process) to rotate it.
func SetAuthToken(token string) {
	authTokenMu.Lock()
	defer authTokenMu.Unlock()
	authToken = token
}

func validToken(header string) bool {
	authTokenMu.RLock()
	expected := authToken
	authTokenMu.RUnlock()

	// Fail closed: with no token configured, nothing is accepted.
	if expected == "" {
		return false
	}

	presented, ok := strings.CutPrefix(header, "Bearer ")
	if !ok {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(presented), []byte(expected)) == 1
}

// Secure rejects requests with an unexpected Host header or a missing/invalid token.
func Secure(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !allowedHosts[r.Host] {
			utils.Error(w, http.StatusForbidden, constants.InvalidHost)
			return
		}

		if !validToken(r.Header.Get("Authorization")) {
			utils.Error(w, http.StatusUnauthorized, constants.Unauthorized)
			return
		}

		next.ServeHTTP(w, r)
	})
}
